QUESTIONS_BY_ID = {item.id: item for item in SALGADO_QUESTIONS}


def shuffled_questions(seed: int) -> tuple[SalgadoQuestion, ...]:
    items = list(SALGADO_QUESTIONS)
    random.Random(seed).shuffle(items)
    return tuple(items)
